begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(13);
insert into employees(id,full_name,position) values('aa100000-0000-4000-8000-000000000001','Payment owner','owner_admin'),('aa100000-0000-4000-8000-000000000002','Payment cashier','kasir');
insert into suppliers(id,name) values('aa200000-0000-4000-8000-000000000001','Payment supplier');
insert into purchase_invoices(id,supplier_id,invoice_number,invoice_date,total_amount,created_by,updated_by) values('aa300000-0000-4000-8000-000000000001','aa200000-0000-4000-8000-000000000001','PAY-1','2026-10-29',100,'aa100000-0000-4000-8000-000000000001','aa100000-0000-4000-8000-000000000001');
create temporary table before_payment as select (select md5(coalesce(string_agg(row_to_json(p)::text,',' order by id),'')) from products p) products,(select md5(coalesce(string_agg(row_to_json(u)::text,',' order by id),'')) from product_units u) units,(select md5(coalesce(string_agg(row_to_json(b)::text,',' order by id),'')) from product_batches b) batches;
select lives_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001','aa400000-0000-4000-8000-000000000001','aa100000-0000-4000-8000-000000000001',40,'2026-10-29')$$,'partial payment');
select is((select sum(amount) from purchase_invoice_payments where invoice_id='aa300000-0000-4000-8000-000000000001'),40::numeric,'partial amount stored');
select lives_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001','aa400000-0000-4000-8000-000000000001','aa100000-0000-4000-8000-000000000001',40,'2026-10-29')$$,'same retry succeeds');
select is((select count(*)::integer from purchase_invoice_payments where invoice_id='aa300000-0000-4000-8000-000000000001'),1,'retry does not duplicate');
select throws_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001','aa400000-0000-4000-8000-000000000001','aa100000-0000-4000-8000-000000000001',41,'2026-10-29')$$,'P0001','INVOICE_REQUEST_CONFLICT','retry key cannot change amount');
select throws_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001',gen_random_uuid(),'aa100000-0000-4000-8000-000000000002',1,'2026-10-29')$$,'P0001','FORBIDDEN','cashier forbidden');
select throws_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001',gen_random_uuid(),'aa100000-0000-4000-8000-000000000001',61,'2026-10-29')$$,'P0001','INVOICE_PAYMENT_EXCEEDS_BALANCE','overpayment rejected');
select throws_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001',gen_random_uuid(),'aa100000-0000-4000-8000-000000000001',0,'2026-10-29')$$,'P0001','INVALID_INVOICE_PAYMENT','zero rejected');
select lives_ok($$select record_purchase_invoice_payment('aa300000-0000-4000-8000-000000000001',gen_random_uuid(),'aa100000-0000-4000-8000-000000000001',60,'2026-10-30')$$,'final payment');
select is((select sum(amount) from purchase_invoice_payments where invoice_id='aa300000-0000-4000-8000-000000000001'),100::numeric,'invoice fully paid');
select ok((select bool_and(recorded_by='aa100000-0000-4000-8000-000000000001' and created_at is not null and payment_date is not null) from purchase_invoice_payments where invoice_id='aa300000-0000-4000-8000-000000000001'),'actor timestamp and payment date stored');
select ok(not has_function_privilege('authenticated','record_purchase_invoice_payment(uuid,uuid,uuid,numeric,date)','EXECUTE'),'browser cannot call payment RPC');
select results_eq($$select (select md5(coalesce(string_agg(row_to_json(p)::text,',' order by id),'')) from products p),(select md5(coalesce(string_agg(row_to_json(u)::text,',' order by id),'')) from product_units u),(select md5(coalesce(string_agg(row_to_json(b)::text,',' order by id),'')) from product_batches b)$$,$$select * from before_payment$$,'payments leave stock and prices unchanged');
select * from finish();
rollback;
